## Working with JSON

### Parsing JSON

```xiom
use xiom.json;

fn main() -> Int {
  let raw = "{\"name\": \"Kilo\", \"version\": 2, \"active\": true}";
  let value = json::parse(raw)?;

  // Access fields
  let name = value["name"].as_str().unwrap();
  let version = value["version"].as_int().unwrap();
  let active = value["active"].as_bool().unwrap();

  io.println("Name: " + name);
  return 0;
}
```

### Creating JSON

```xiom
use xiom.json;

fn main() -> Int {
  let obj = json::Object::new();
  obj.insert("name", json::Value::Str("Kilo"));
  obj.insert("version", json::Value::Int(2));
  obj.insert("features", json::Value::Array([
    json::Value::Str("fast"),
    json::Value::Str("safe"),
  ]));

  let output = json::to_string(&obj);
  io.println(output);
  return 0;
}
```

### Type-Safe Serialization

```xiom
#[derive(Serialize, Deserialize)]
pub type Config = {
  host: Str;
  port: Int;
  features: Vec[Str];
}

fn main() -> Int {
  // Deserialize JSON → Config
  let raw = fs::read_to_str("config.json")?;
  let config: Config = json::from_str(&raw)?;

  io.println("Server: " + config.host + ":" + config.port.to_str());

  // Serialize Config → JSON
  config.host = "0.0.0.0";
  let output = json::to_string_pretty(&config);
  fs::write("config.json", &output)?;
  return 0;
}
```

### JSON Value Types

```xiom
match value {
  json::Value::Null => "null",
  json::Value::Bool(b) => b.to_str(),
  json::Value::Int(n) => n.to_str(),
  json::Value::Float(f) => f.to_str(),
  json::Value::Str(s) => s,
  json::Value::Array(arr) => "[" + arr.len().to_str() + " items]",
  json::Value::Object(obj) => "{" + obj.len().to_str() + " keys}",
}
```

### API Client Example

```xiom
fn fetch_user(id: Int) -> Result[User, Error] {
  let url = "https://api.example.com/users/" + id.to_str();
  let response = http::get(url)?;
  let user: User = json::from_str(&response.body)?;
  return Ok(user);
}
```

