pub type Person = { name: Str; age: Int; email: Str; }

fn parse_person(json_str: Str) -> Person {
  // Simple manual parsing for exercise
  let name_start = json_str.find("\"name\"") + 8;
  let name_end = json_str[name_start..].find("\"") + name_start;
  let name = json_str[name_start..name_end];

  let age_start = json_str.find("\"age\"") + 6;
  let age_end = json_str[age_start..].find(",") + age_start;
  let age = json_str[age_start..age_end].parse_int().unwrap();

  return Person{ name: name, age: age, email: "" };
}

fn main() -> Int {
  let p = parse_person("{\"name\":\"Alice\",\"age\":30,\"email\":\"alice@example.com\"}");
  return p.age;
}
